package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotatedParameter;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class POJOPropertyBuilder_removeNonVisible_TriageGen2Test {

    private MapperConfig<?> mockConfig;
    private AnnotationIntrospector mockAi;
    private PropertyName mockName;

    @Before
    public void setUp() {
        mockConfig = mock(MapperConfig.class);
        mockAi = mock(AnnotationIntrospector.class);
        mockName = PropertyName.construct("testProperty");
    }

    /**
     * Helper to create a builder with specific state.
     * Since we cannot easily mock protected fields like _fields, _getters, etc., 
     * we use the public API to populate them.
     */
    private POJOPropertyBuilder createBuilder(boolean forSerialization) {
        return new POJOPropertyBuilder(mockConfig, mockAi, forSerialization, mockName);
    }

    @Test
    public void testRemoveNonVisible_READ_ONLY_forSerialization() {
        // READ_ONLY: _setters = null, _ctorParameters = null. 
        // If !_forSerialization, _fields = null.
        // Since forSerialization is true, _fields should NOT be nulled by this logic.

        POJOPropertyBuilder builder = createBuilder(true);
        // We need to simulate findAccess() returning READ_ONLY. 
        // Since findAccess is protected, we rely on the fact that we can't easily override it 
        // without a subclass or Spying.

        POJOPropertyBuilder spyBuilder = spy(builder);
        doReturn(JsonProperty.Access.READ_ONLY).when(spyBuilder).findAccess();

        // Setup members
        AnnotatedMethod getter = mock(AnnotatedMethod.class);
        AnnotatedMethod setter = mock(AnnotatedMethod.class);
        AnnotatedField field = mock(AnnotatedField.class);
        AnnotatedParameter ctor = mock(AnnotatedParameter.class);

        spyBuilder.addGetter(getter, mockName, false, true, false);
        spyBuilder.addSetter(setter, mockName, false, true, false);
        spyBuilder.addField(field, mockName, false, true, false);
        spyBuilder.addCtor(ctor, mockName, false, true, false);

        spyBuilder.removeNonVisible(true);

        assertFalse("Setter should be removed", spyBuilder.hasSetter());
        assertFalse("Ctor should be removed", spyBuilder.hasConstructorParameter());
        assertTrue("Field should remain because forSerialization is true", spyBuilder.hasField());
    }

    @Test
    public void testRemoveNonVisible_READ_ONLY_notForSerialization() {
        POJOPropertyBuilder builder = createBuilder(false);
        POJOPropertyBuilder spyBuilder = spy(builder);
        doReturn(JsonProperty.Access.READ_ONLY).when(spyBuilder).findAccess();

        AnnotatedMethod setter = mock(AnnotatedMethod.class);
        AnnotatedField field = mock(AnnotatedField.class);
        AnnotatedParameter ctor = mock(AnnotatedParameter.class);

        spyBuilder.addSetter(setter, mockName, false, true, false);
        spyBuilder.addField(field, mockName, false, true, false);
        spyBuilder.addCtor(ctor, mockName, false, true, false);

        spyBuilder.removeNonVisible(true);

        assertFalse(spyBuilder.hasSetter());
        assertFalse(spyBuilder.hasConstructorParameter());
        assertFalse("Field should be removed because forSerialization is false", spyBuilder.hasField());
    }

    @Test
    public void testRemoveNonVisible_READ_WRITE() {
        POJOPropertyBuilder builder = createBuilder(true);
        POJOPropertyBuilder spyBuilder = spy(builder);
        doReturn(JsonProperty.Access.READ_WRITE).when(spyBuilder).findAccess();

        AnnotatedMethod getter = mock(AnnotatedMethod.class);
        AnnotatedMethod setter = mock(AnnotatedMethod.class);
        AnnotatedField field = mock(AnnotatedField.class);

        spyBuilder.addGetter(getter, mockName, false, true, false);
        spyBuilder.addSetter(setter, mockName, false, true, false);
        spyBuilder.addField(field, mockName, false, true, false);

        spyBuilder.removeNonVisible(true);

        assertTrue(spyBuilder.hasGetter());
        assertTrue(spyBuilder.hasSetter());
        assertTrue(spyBuilder.hasField());
    }

    @Test
    public void testRemoveNonVisible_WRITE_ONLY_forSerialization() {
        POJOPropertyBuilder builder = createBuilder(true);
        POJOPropertyBuilder spyBuilder = spy(builder);
        doReturn(JsonProperty.Access.WRITE_ONLY).when(spyBuilder).findAccess();

        AnnotatedMethod getter = mock(AnnotatedMethod.class);
        AnnotatedField field = mock(AnnotatedField.class);

        spyBuilder.addGetter(getter, mockName, false, true, false);
        spyBuilder.addField(field, mockName, false, true, false);

        spyBuilder.removeNonVisible(true);

        assertFalse("Getter should be removed", spyBuilder.hasGetter());
        assertFalse("Field should be removed because forSerialization is true", spyBuilder.hasField());
    }

    @Test
    public void testRemoveNonVisible_WRITE_ONLY_notForSerialization() {
        POJOPropertyBuilder builder = createBuilder(false);
        POJOPropertyBuilder spyBuilder = spy(builder);
        doReturn(JsonProperty.Access.WRITE_ONLY).when(spyBuilder).findAccess();

        AnnotatedMethod getter = mock(AnnotatedMethod.class);
        AnnotatedField field = mock(AnnotatedField.class);

        spyBuilder.addGetter(getter, mockName, false, true, false);
        spyBuilder.addField(field, mockName, false, true, false);

        spyBuilder.removeNonVisible(true);

        assertFalse(spyBuilder.hasGetter());
        assertTrue("Field should remain because forSerialization is false", spyBuilder.hasField());
    }

    @Test
    public void testRemoveNonVisible_AUTO_inferMutatorsTrue() {
        POJOPropertyBuilder builder = createBuilder(true);
        POJOPropertyBuilder spyBuilder = spy(builder);
        // Default findAccess is null, which falls to AUTO
        doReturn(null).when(spyBuilder).findAccess();

        AnnotatedMethod getter = mock(AnnotatedMethod.class);
        AnnotatedMethod setter = mock(AnnotatedMethod.class);
        AnnotatedField field = mock(AnnotatedField.class);
        AnnotatedParameter ctor = mock(AnnotatedParameter.class);

        spyBuilder.addGetter(getter, mockName, false, true, false);
        spyBuilder.addSetter(setter, mockName, false, true, false);
        spyBuilder.addField(field, mockName, false, true, false);
        spyBuilder.addCtor(ctor, mockName, false, true, false);

        // When inferMutators is true, _fields and _setters are only removed 
        // if _getters becomes null after _removeNonVisible call.
        // We simulate visibility by making the getter "visible" so _removeNonVisible doesn't null it.
        // However, _removeNonVisible is a protected method that handles the actual logic.
        // Since we can't mock the internal _removeNonVisible easily without more complex mocking,
        // we assume standard visibility.

        spyBuilder.removeNonVisible(true);

        // In AUTO mode with inferMutators=true:
        // getters = _removeNonVisible(getters)
        // ctor = _removeNonVisible(ctor)
        // if (!true || (getters == null)) -> false. So fields/setters are NOT processed via _removeNonVisible.

        assertTrue(spyBuilder.hasGetter());
        assertTrue(spyBuilder.hasSetter());
        assertTrue(spyBuilder.hasField());
        assertTrue(spyBuilder.hasConstructorParameter());
    }

    @Test
    public void testRemoveNonVisible_AUTO_inferMutatorsFalse() {
        POJOPropertyBuilder builder = createBuilder(true);
        POJOPropertyBuilder spyBuilder = spy(builder);
        doReturn(JsonProperty.Access.AUTO).when(spyBuilder).findAccess();

        AnnotatedMethod getter = mock(AnnotatedMethod.class);
        AnnotatedMethod setter = mock(AnnotatedMethod.class);
        AnnotatedField field = mock(AnnotatedField.class);
        AnnotatedParameter ctor = mock(AnnotatedParameter.class);

        spyBuilder.addGetter(getter, mockName, false, true, false);
        spyBuilder.addSetter(setter, mockName, false, true, false);
        spyBuilder.addField(field, mockName, false, true, false);
        spyBuilder.addCtor(ctor, mockName, false, true, false);

        // When inferMutators is false, _fields and _setters ARE processed via _removeNonVisible
        spyBuilder.removeNonVisible(false);

        // Since we added them as visible, they should remain.
        assertTrue(spyBuilder.hasGetter());
        assertTrue(spyBuilder.hasSetter());
        assertTrue(spyBuilder.hasField());
        assertTrue(spyBuilder.hasConstructorParameter());
    }

    @Test
    public void testRemoveNonVisible_AUTO_gettersNullified() {
        POJOPropertyBuilder builder = createBuilder(true);
        POJOPropertyBuilder spyBuilder = spy(builder);
        doReturn(JsonProperty.Access.AUTO).when(spyBuilder).findAccess();

        // Add a field/setter but NO getter
        AnnotatedMethod setter = mock(AnnotatedMethod.class);
        AnnotatedField field = mock(AnnotatedField.class);
        spyBuilder.addSetter(setter, mockName, false, true, false);
        spyBuilder.addField(field, mockName, false, true, false);

        // To trigger the (_getters == null) condition, we need _removeNonVisible to return null.
        // This happens if there are no visible getters.
        // Since we didn't add a getter, _getters is already null or empty.

        spyBuilder.removeNonVisible(true);

        // If _getters is null, then _fields and _setters are passed to _removeNonVisible.
        // Since they are visible, they should still exist.
        assertTrue(spyBuilder.hasSetter());
        assertTrue(spyBuilder.hasField());
    }
}
